package main
import("context";"encoding/json";"errors";"fmt";"os";"time";"github.com/google/uuid";"github.com/jackc/pgx/v5/pgxpool";"photoeditor/backend/internal/artifactjson";"photoeditor/backend/internal/database";"photoeditor/backend/internal/objectstore";"photoeditor/backend/internal/workflow")
type scopeLeases struct{workflow.SQLIngestLeases;allowed map[uuid.UUID]bool;tenant uuid.UUID}
func(s scopeLeases)Claim(c context.Context)(*workflow.IngestBuildLease,error){l,e:=s.SQLIngestLeases.Claim(c);if e!=nil||l==nil{return l,e};if !s.allowed[l.RunID]||l.TenantID!=s.tenant{_,_=s.SQLIngestLeases.Release(c,*l);return nil,errors.New("unexpected ingest scope")};return l,nil}
type planning struct{reader workflow.IngestRunReader;builder workflow.IngestInspectionCoordinator;tasks map[uuid.UUID]bool;runs map[uuid.UUID]bool}
func(p *planning)Advance(c context.Context,t,r uuid.UUID)(bool,error){state,e:=p.reader.Load(c,t,r);if e!=nil{return false,e};if state.Phase!="planning"&&state.Phase!="inspection"{return false,errors.New("unexpected ingest phase")};registry,e:=workflow.LoadRegistry();if e!=nil{return false,e};plan,e:=workflow.CompileIngest(state.Spec,registry);if e!=nil{return false,e};for _,n:=range plan.Nodes{if n.Operation=="asset.verify"||n.Operation=="asset.inspect"{p.tasks[n.ID]=true}};if state.Phase=="planning"{if e=p.builder.PrepareInspection(c,t,state.Spec);e!=nil{return false,e}};p.runs[r]=true;return true,nil}
type activationScope struct{workflow.IngestActivationSource;tasks map[uuid.UUID]bool}
func(s activationScope)Pending(c context.Context,n int)([]workflow.BoundTaskActivation,error){rows,e:=s.IngestActivationSource.Pending(c,n);if e!=nil{return nil,e};for _,row:=range rows{if !s.tasks[row.TaskID]{return nil,errors.New("unexpected activation scope")}};return rows,nil}
func run()error{ctx,cancel:=context.WithTimeout(context.Background(),5*time.Minute);defer cancel();var ids []uuid.UUID;if json.Unmarshal([]byte(os.Getenv("EXPECTED_RUN_IDS")),&ids)!=nil||len(ids)!=6{return errors.New("expected six runs")};tenant,e:=uuid.Parse(os.Getenv("EXPECTED_TENANT_ID"));if e!=nil{return e};allowed:=map[uuid.UUID]bool{};for _,id:=range ids{if id==uuid.Nil||allowed[id]{return errors.New("invalid run scope")};allowed[id]=true};cfg,e:=pgxpool.ParseConfig(os.Getenv("DATABASE_URL"));if e!=nil{return e};cfg.MaxConns=2;cfg.ConnConfig.RuntimeParams["role"]="photo_scheduler";cfg.ConnConfig.RuntimeParams["statement_timeout"]="5000";cfg.ConnConfig.RuntimeParams["lock_timeout"]="3000";database.GuardApplicationRole(cfg);pool,e:=pgxpool.NewWithConfig(ctx,cfg);if e!=nil{return e};defer pool.Close();if e=database.RequireApplicationRole(ctx,pool,"photo_scheduler");e!=nil{return e};config:=objectstore.ConfigFromEnv(true);store,e:=objectstore.New(config);if e!=nil{return e};plans:=workflow.IngestPlanRepository{DB:pool};publisher:=artifactjson.Publisher{Repository:artifactjson.SQLRepository{DB:pool,Bucket:config.Bucket},Objects:store};p:=&planning{reader:workflow.IngestRunReader{DB:pool},builder:workflow.IngestInspectionCoordinator{Documents:workflow.IngestDocumentBuilder{Plans:plans,Publisher:publisher},Tasks:plans},tasks:map[uuid.UUID]bool{},runs:map[uuid.UUID]bool{}};processor:=workflow.IngestProcessor{Leases:scopeLeases{workflow.SQLIngestLeases{DB:pool},allowed,tenant},Runner:p};for range ids{ok,e:=processor.ProcessOne(ctx);if e!=nil{return e};if !ok{return errors.New("ingest planning did not confirm")}};if len(p.runs)!=6||len(p.tasks)!=12{return errors.New("inspection planning scope incomplete")};activator:=workflow.IngestActivator{Source:activationScope{workflow.IngestActivationSource{DB:pool},p.tasks},Tasks:workflow.AdvancementRepository{DB:pool}};n,e:=activator.Advance(ctx,100);if e!=nil{return e};fmt.Printf("{\"status\":\"ACTUAL_INGEST_PLANNING_PASS\",\"runs\":6,\"inspection_tasks\":12,\"activation_confirmations\":%d,\"scheduler_started\":false}\n",n);return nil}
func main(){if e:=run();e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
